    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(math.sqrt(n)) + 1):
            if n % i == 0:
                return False
        return True

    for i in range(2, int(a ** (1/3)) + 1):
        if a % i == 0:
            for j in range(i, int((a // i) ** (1/2)) + 1):
                if (a // i) % j == 0:
