def sum_of_divisors(n):
    """
    Calculate the sum of all divisors of a given integer n.
    """
    divisors = set()
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            divisors.add(i)
            divisors.add(n // i)
    return sum(divisors)

def are_equivalent(a, b):
    """
    Determine if the sum of the divisors of two integers a and b are the same.
    """
    return sum_of_divisors(a) == sum_of_divisors(b)
